"use strict";(globalThis.webpackChunkmy_docs=globalThis.webpackChunkmy_docs||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Cloud","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/","label":"Introduction","docId":"cloud/intro","unlisted":false},{"type":"link","href":"/docs/cloud/getting-started","label":"Getting Started","docId":"cloud/getting-started","unlisted":false},{"type":"link","href":"/docs/cloud/api-reference","label":"API Reference","docId":"cloud/api-reference","unlisted":false},{"type":"link","href":"/docs/cloud/architecture","label":"Architecture","docId":"cloud/architecture","unlisted":false},{"type":"link","href":"/docs/cloud/deployment","label":"Deployment","docId":"cloud/deployment","unlisted":false}],"href":"/docs/category/cloud"},{"type":"category","label":"Hardware","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/hardware/overview","label":"Hardware Overview","docId":"hardware/overview","unlisted":false},{"type":"link","href":"/docs/hardware/bom","label":"Bill of Materials","docId":"hardware/bom","unlisted":false}],"href":"/docs/category/hardware"}]},"docs":{"cloud/api-reference":{"id":"cloud/api-reference","title":"API Reference","description":"The Wildfire Alarm API is plain HTTP and JSON. In Docker deployments the dashboard reaches it under /api/ on the same host, for example https//localhost:3000.","sidebar":"tutorialSidebar"},"cloud/architecture":{"id":"cloud/architecture","title":"Architecture","description":"System overview","sidebar":"tutorialSidebar"},"cloud/deployment":{"id":"cloud/deployment","title":"Deployment","description":"Wildfire Alarm runs as three containers from biobot-infrastructure: MariaDB, the API, and the dashboard (nginx serving the React build and proxying /api/ to the API). One public hostname is enough.","sidebar":"tutorialSidebar"},"cloud/getting-started":{"id":"cloud/getting-started","title":"Getting Started","description":"Run the whole stack (database, API and dashboard) on your machine, then feed it data from a simulated node. No hardware or Notehub account is needed.","sidebar":"tutorialSidebar"},"cloud/intro":{"id":"cloud/intro","title":"Wildfire Alarm Cloud","description":"biobot-cloud is the server-side backend for Wildfire Alarm. It is a Node.js / Express API on MariaDB (Sequelize ORM) that receives sensor data from Blues Notehub, turns node alerts into incidents, emails the hosts, and serves the dashboard.","sidebar":"tutorialSidebar"},"hardware/bom":{"id":"hardware/bom","title":"Bill of Materials","description":"Select your preferred vendor for each component to calculate your build cost.","sidebar":"tutorialSidebar"},"hardware/overview":{"id":"hardware/overview","title":"Hardware Overview","description":"A Wildfire Alarm node is a carrier PCB that holds off-the-shelf modules and gives them clean power and sensor connectors. The current board is Fire Detection Device, rev A. Its design files, gerbers and BOM are in biobot-hardware.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Wildfire Alarm is an open-source sensor network for early wildfire detection. Low-cost nodes placed at the forest edge sample the air every 30 seconds, decide on the node itself whether something looks like smoke or fire, and report over cellular to a cloud service that opens an incident and emails the people responsible for that area.","sidebar":"tutorialSidebar"}}}}')}}]);